"""Evergreen, mindset-first topic blueprints for The Finance Campus.

These topics begin with human money behaviours and beliefs, not financial headlines.
The linked official sources are research checks, not prompts to publish news summaries.
"""
from __future__ import annotations

from typing import Any

MINDSET_TOPIC_BLUEPRINTS: list[dict[str, Any]] = [
    {"slug":"looking-rich-vs-being-secure","title":"Looking rich can keep you financially stuck","category":"Financial Psychology","source":"bou_literacy","keywords":["financial","literacy"],"geo":["Uganda","East Africa"],"problem":"People can feel pressure to display success through clothes, phones, cars or expensive outings.","stakes":"When appearances take priority over financial priorities, money meant for essentials, savings or goals can disappear into comparison.","explanation":"Financial wellbeing is about resilience and choices, not how wealthy someone appears. Spending decisions should reflect personal priorities rather than pressure to impress others.","action":"Before your next status purchase, ask whether you would still want it if nobody else could see it."},
    {"slug":"income-up-spending-up","title":"Why earning more does not always make you wealthier","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","spending"],"geo":["global","Uganda","East Africa"],"problem":"When income rises, people often upgrade several parts of their lifestyle without deciding what the extra money should achieve.","stakes":"If every increase in income is absorbed by new spending, financial pressure can remain even while earnings grow.","explanation":"Lifestyle inflation happens when spending rises alongside income. Choosing priorities before upgrading can help turn some additional income into stability and progress.","action":"When income increases, decide in advance how much will support essentials, future goals and optional lifestyle upgrades."},
    {"slug":"emotional-spending","title":"Are you buying what you need or buying how you want to feel?","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["spending","financial"],"geo":["global","Uganda","East Africa"],"problem":"Stress, boredom, sadness or excitement can trigger purchases that feel comforting in the moment.","stakes":"Repeated emotional spending can leave less money for priorities and may create regret or financial anxiety later.","explanation":"Not every purchase is purely practical. Recognising the emotion behind a spending urge creates a chance to choose deliberately rather than react automatically.","action":"Before a non-essential purchase, name the feeling you are responding to and give yourself time to decide."},
    {"slug":"comparison-trap","title":"The money comparison trap: someone else's lifestyle is not your budget","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","financial"],"geo":["global","Uganda","East Africa"],"problem":"Seeing friends, relatives or online personalities spend can make an ordinary life feel inadequate.","stakes":"Copying spending you cannot comfortably afford can create debt, conflict and pressure that are invisible to everyone watching.","explanation":"People have different incomes, obligations, support systems and debts. A visible lifestyle does not reveal someone's full financial position.","action":"Choose one personal financial priority and measure progress against your own starting point, not another person's display."},
    {"slug":"pay-yourself-later-myth","title":"Why waiting until you have more money to start saving can keep you waiting","category":"Saving and Emergency Funds","source":"cfpb_emergency","keywords":["saving","emergency"],"geo":["global","Uganda","East Africa"],"problem":"People may postpone saving because the amount they can set aside today feels too small to matter.","stakes":"Repeated postponement can leave every unexpected cost competing with money needed for daily essentials.","explanation":"A saving habit is built through consistency and a realistic amount, not by waiting for a perfect income or a perfect month.","action":"Choose a small contribution that does not endanger essentials and repeat it on a schedule you can maintain."},
    {"slug":"money-avoidance","title":"The cost of avoiding your money problems","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","decisions"],"geo":["global","Uganda","East Africa"],"problem":"Opening bills, checking balances or listing debts can feel frightening, so people sometimes avoid looking.","stakes":"Avoidance can allow due dates, fees and uncertainty to pile up, making the problem feel even larger.","explanation":"Knowing the situation does not solve everything, but it gives you a starting point for choosing what needs attention first.","action":"Set a ten-minute timer, gather the facts without judging yourself, and write down just the next issue to address."},
    {"slug":"small-leaks-big-pressure","title":"Small spending habits can quietly take control of your money","category":"Budgeting and Money Management","source":"cfpb_toolkit","keywords":["spending","budget"],"geo":["global","Uganda","East Africa"],"problem":"Frequent small purchases can feel harmless because each one seems affordable on its own.","stakes":"When repeated without awareness, they can crowd out priorities and leave a person wondering where the money went.","explanation":"A spending pattern matters more than any single small purchase. Tracking behaviour helps reveal which habits are worth changing.","action":"Record every small discretionary purchase for seven days and identify one pattern you want to change."},
    {"slug":"debt-as-false-relief","title":"When borrowing feels like relief but becomes another burden","category":"Debt and Loans","source":"bou_literacy","keywords":["credit","financial"],"geo":["Uganda","East Africa"],"problem":"Borrowing can feel like an immediate solution when income cannot cover today's needs or wants.","stakes":"If the reason for the shortfall remains unchanged, repayments can make future months even tighter.","explanation":"A loan moves money across time; it does not create extra income. Understanding the reason for borrowing and the full repayment obligation matters before deciding.","action":"Before borrowing, write down what problem the loan solves, what it will cost in total and how repayments fit alongside essentials."},
    {"slug":"one-more-loan-cycle","title":"The dangerous cycle of borrowing to feel financially okay","category":"Debt and Loans","source":"bou_literacy","keywords":["debt","loan"],"geo":["Uganda","East Africa"],"problem":"A person under pressure may take a new loan to cover an old payment or restore spending money.","stakes":"Repeated borrowing can postpone the underlying problem while increasing obligations and stress.","explanation":"When new debt is needed to service existing debt, it is a signal to pause and review the full situation rather than automatically borrow again.","action":"List all current obligations and speak with the lender or a qualified support service before taking another loan."},
    {"slug":"money-boundaries-family-pressure","title":"How to say no when family and friends expect your money","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","financial"],"geo":["global","Uganda","East Africa"],"problem":"Requests for help can be emotionally difficult, especially when they come from people you care about.","stakes":"Giving beyond your means can put rent, food, school costs or your own dependants at risk and create resentment.","explanation":"Generosity and financial boundaries can coexist. A clear limit helps you support others without making promises your finances cannot sustain.","action":"Decide what support you can genuinely afford before a request arrives, and practise explaining that limit respectfully."},
    {"slug":"instant-gratification","title":"Why choosing comfort today can cost you choices tomorrow","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","saving"],"geo":["global","Uganda","East Africa"],"problem":"Immediate rewards can feel more real than a future goal that is months or years away.","stakes":"When every spare amount is spent immediately, longer-term goals may never receive consistent attention.","explanation":"Delayed gratification is the ability to balance today's wants with tomorrow's priorities. It is not about never enjoying money; it is about choosing intentionally.","action":"Pick one goal that matters to you and move a small amount toward it before spending on optional wants."},
    {"slug":"no-plan-no-direction","title":"If you do not give your money a direction, it will find one","category":"Budgeting and Money Management","source":"cfpb_toolkit","keywords":["budget","goals"],"geo":["global","Uganda","East Africa"],"problem":"Without a plan, spending decisions are often made one moment at a time.","stakes":"Urgent requests and tempting purchases can consume money before important obligations and goals are covered.","explanation":"A simple spending plan gives income a purpose before it is spent. It can be flexible and should reflect real circumstances.","action":"Before your next pay or business income arrives, write down the three most important jobs that money needs to do."},
    {"slug":"shame-keeps-you-stuck","title":"Money shame makes it harder to make a fresh start","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","goals"],"geo":["global","Uganda","East Africa"],"problem":"People may hide money mistakes because they fear judgement from family, friends or themselves.","stakes":"Shame can delay asking questions, seeking support or taking the first practical step toward change.","explanation":"A financial mistake is information about a decision or circumstance, not a permanent identity. Honest review is more useful than self-punishment.","action":"Write down one money lesson from the past without insulting yourself, then choose one different action for next time."},
    {"slug":"scarcity-and-short-term-thinking","title":"Why financial pressure can make tomorrow harder to think about","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","decisions"],"geo":["global","Uganda","East Africa"],"problem":"When money is constantly tight, immediate needs can consume nearly all attention.","stakes":"Long-term planning may feel impossible, even when small protective steps could reduce future pressure.","explanation":"Scarcity and uncertainty can narrow the choices people feel able to consider. Advice must respect real constraints rather than blame people for them.","action":"Focus on one manageable decision within your control this week; do not measure yourself against someone with different resources."},
    {"slug":"irregular-income-no-routine","title":"How to manage money when payday is never predictable","category":"Budgeting and Money Management","source":"cfpb_toolkit","keywords":["income","cash"],"geo":["global","Uganda","East Africa"],"problem":"Freelancers, traders and casual workers may not know exactly when or how much money will arrive.","stakes":"A fixed monthly routine may fail when income changes, leading to avoidable shortages or rushed decisions.","explanation":"A flexible system can prioritise essentials, track upcoming obligations and make saving responsive to actual cash flow.","action":"Write down essential costs and due dates, then decide how each incoming payment will be divided before optional spending."},
    {"slug":"emergency-is-not-unlucky","title":"An emergency fund is not pessimism; it is preparation","category":"Saving and Emergency Funds","source":"cfpb_emergency","keywords":["emergency","saving"],"geo":["global","Uganda","East Africa"],"problem":"Preparing for setbacks can feel unnecessary when everything is currently going well.","stakes":"Without a buffer, an ordinary disruption can force difficult trade-offs or borrowing at the worst moment.","explanation":"Emergency savings are a practical form of self-protection, not a prediction that something bad will happen.","action":"Name one realistic disruption that could affect your household and decide what first small preparation is possible."},
    {"slug":"financial-success-is-not-speed","title":"You do not need to get rich quickly to make financial progress","category":"Wealth Creation","source":"sec_investor","keywords":["investing","risk"],"geo":["global"],"problem":"Stories of sudden wealth can make steady progress feel boring or inadequate.","stakes":"Chasing speed can make people more vulnerable to unrealistic promises, reckless risks or scams.","explanation":"Sustainable financial progress is usually built through informed choices, risk awareness, patience and consistency; no approach guarantees wealth.","action":"Set one realistic financial goal and identify a repeatable step that supports it without relying on a promise of quick returns."},
    {"slug":"money-goals-need-identity","title":"Become the person who follows through on money goals","category":"Wealth Creation","source":"cfpb_toolkit","keywords":["goals","saving"],"geo":["global","Uganda","East Africa"],"problem":"People often set ambitious financial goals but rely only on motivation to keep going.","stakes":"When motivation fades, the goal can disappear from everyday decisions.","explanation":"A repeatable routine, clear reminder and manageable action can make a goal easier to maintain than relying on willpower alone.","action":"Attach one small money action to an existing weekly routine and review it at the same time each week."},
    {"slug":"financial-independence-starts-with-awareness","title":"Financial independence starts before you become wealthy","category":"Wealth Creation","source":"cfpb_toolkit","keywords":["financial","goals"],"geo":["global","Uganda","East Africa"],"problem":"Financial independence can seem like a distant destination reserved for people with high incomes.","stakes":"If it feels unreachable, people may ignore the smaller choices that can improve their current level of control.","explanation":"Greater financial independence begins with understanding obligations, making deliberate choices and gradually building options; the path differs by circumstance.","action":"Identify one recurring expense, obligation or habit you can understand better this week and decide whether it still serves your priorities."},
    {"slug":"do-not-confuse-income-with-worth","title":"Your income does not determine your worth","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","wellbeing"],"geo":["global","Uganda","East Africa"],"problem":"People may judge their value by salary, possessions or how quickly they appear to progress.","stakes":"That pressure can lead to overwork, unhealthy comparison and spending decisions made to prove personal worth.","explanation":"Income is a financial resource, not a measure of human value. A healthy money plan should serve a person's real needs and values.","action":"Write down what financial stability would mean in your own life, without using another person's lifestyle as the benchmark."},
]



# Additional evergreen angles provide a deeper unused-topic reserve for later weeks.
MINDSET_TOPIC_BLUEPRINTS.extend([
    {"slug":"payday-is-not-a-party","title":"Why treating payday like a celebration can keep you broke","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["spending","goals"],"geo":["global","Uganda","East Africa"],"problem":"After working hard, it can feel natural to spend freely as soon as income arrives.","stakes":"If essentials and commitments are not protected first, the rest of the pay period can become a cycle of shortage and stress.","explanation":"Enjoying income is reasonable, but deciding its priorities before spending helps balance present enjoyment with future needs.","action":"On your next payday, assign money to essential costs and one future goal before deciding what is available for treats."},
    {"slug":"windfall-disappears","title":"Why unexpected money can disappear faster than it arrived","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","saving"],"geo":["global","Uganda","East Africa"],"problem":"A bonus, gift or unusually good business day can create the feeling that the money is extra and has no purpose.","stakes":"Without a pause, a temporary increase can be spent quickly without improving financial stability.","explanation":"A windfall is an opportunity to make a deliberate choice, not a reason to abandon priorities. Its best use depends on the person's circumstances.","action":"Before spending unexpected money, wait a day and decide what portion should support an important need or goal."},
    {"slug":"budget-is-not-punishment","title":"A budget is not a punishment; it is permission to choose","category":"Budgeting and Money Management","source":"cfpb_toolkit","keywords":["budget","goals"],"geo":["global","Uganda","East Africa"],"problem":"Some people avoid budgeting because they think it means giving up every enjoyable purchase.","stakes":"Without a plan, money can be spent by default, leaving less control over both needs and wants.","explanation":"A useful budget is a choice-making tool. It should reflect real priorities and leave room for enjoyment where possible.","action":"Build a simple plan that includes one realistic amount for enjoyment instead of pretending you will never spend on wants."},
    {"slug":"saving-is-not-self-denial","title":"Saving money does not mean you must stop enjoying life","category":"Saving and Emergency Funds","source":"cfpb_emergency","keywords":["saving","emergency"],"geo":["global","Uganda","East Africa"],"problem":"Saving can feel like constant sacrifice, especially when income is already limited.","stakes":"An all-or-nothing approach can make a saving plan feel impossible and lead people to abandon it.","explanation":"A sustainable habit balances today's needs with future protection and should be realistic for the income available.","action":"Choose a modest savings target that leaves essential needs covered and review it when your circumstances change."},
    {"slug":"fear-of-investing-paralysis","title":"How fear of making a money mistake can stop you learning","category":"Financial Psychology","source":"sec_investor","keywords":["investing","risk"],"geo":["global"],"problem":"Some people avoid learning about investing because they fear losing money or being embarrassed by a mistake.","stakes":"Avoidance can leave people dependent on rumours or unable to evaluate offers when they encounter them.","explanation":"Learning does not require rushing to invest. Understanding basic risks, fees and product features is a safer first step than acting under pressure.","action":"Choose one basic investing concept to learn from a regulator or established educational source before making any decision."},
    {"slug":"get-rich-quick-appeal","title":"Why get-rich-quick promises are so emotionally powerful","category":"Financial Scams and Fraud Prevention","source":"sec_investor","keywords":["investing","risk"],"geo":["global","Uganda","East Africa"],"problem":"When people feel behind financially, a promise of fast wealth can sound like a way out.","stakes":"Urgency and unrealistic expectations can weaken judgement and make fraudulent or unsuitable offers more tempting.","explanation":"A credible opportunity should be understandable and independently verifiable. High or guaranteed returns with little risk are warning signs, not proof of success.","action":"When an offer promises quick wealth, pause, verify it with the relevant regulator and refuse pressure to act immediately."},
    {"slug":"ask-before-you-sign","title":"The confidence to ask questions can protect your money","category":"Financial Literacy","source":"bou_literacy","keywords":["financial","literacy"],"geo":["Uganda","East Africa"],"problem":"People may agree to financial terms because they feel embarrassed to ask what a fee, penalty or condition means.","stakes":"Signing something you do not understand can create obligations that are difficult to reverse.","explanation":"Asking clear questions is part of informed decision-making. You have the right to understand costs, conditions and risks before agreeing.","action":"Before your next financial commitment, write down what you do not understand and ask the provider to explain it plainly."},
    {"slug":"separate-business-and-personal-money","title":"Why mixing business money with personal spending creates confusion","category":"Entrepreneurship and Business Finance","source":"cfpb_toolkit","keywords":["cash","income"],"geo":["global","Uganda","East Africa"],"problem":"Small business owners may use the same cash for stock, household needs, transport and personal purchases.","stakes":"It becomes difficult to know whether the business is earning, losing money or simply running out of working cash.","explanation":"Separating business and personal records creates a clearer picture of cash flow, even when the business is very small.","action":"Start a simple daily record of business money received, business costs and money taken for personal use."},
    {"slug":"small-business-owner-is-not-cash-register","title":"Your business income is not automatically your personal income","category":"Entrepreneurship and Business Finance","source":"cfpb_toolkit","keywords":["business","cash"],"geo":["global","Uganda","East Africa"],"problem":"When money enters a business, the owner may treat the full amount as available for personal spending.","stakes":"Using sales money before covering stock, operating costs and obligations can leave the business unable to continue.","explanation":"Sales revenue must cover business costs before the owner can understand what is available to take out.","action":"Record sales and business expenses separately, then decide on a consistent and affordable owner withdrawal."},
    {"slug":"talk-about-money-early","title":"Why avoiding money conversations can damage relationships","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","decisions"],"geo":["global","Uganda","East Africa"],"problem":"Partners or family members may avoid discussing spending, debt and responsibilities because the conversation feels uncomfortable.","stakes":"Unspoken expectations can lead to mistrust, surprise obligations and repeated conflict.","explanation":"Respectful money conversations help people understand shared responsibilities and agree on boundaries before problems grow.","action":"Set aside a calm time to discuss one shared financial priority without blame or accusation."},
    {"slug":"teach-by-example","title":"Children learn money habits from what adults do","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","education"],"geo":["global","Uganda","East Africa"],"problem":"Adults may teach children to save while regularly modelling impulsive spending or money secrecy.","stakes":"Mixed messages can make it harder for young people to connect money lessons with everyday behaviour.","explanation":"Age-appropriate conversations and consistent examples can help children understand choices, patience and priorities.","action":"Explain one everyday spending decision to a child and show how you compare a want with a need."},
    {"slug":"financial-setback-not-failure","title":"A financial setback does not erase the progress you made","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","financial"],"geo":["global","Uganda","East Africa"],"problem":"An emergency or missed goal can make someone feel that all previous effort was wasted.","stakes":"That feeling can lead to giving up on useful habits or making rushed decisions to catch up.","explanation":"Plans need to adapt when circumstances change. Progress can include responding wisely to a setback, not only reaching a target on time.","action":"Review what changed, reset one realistic next step and restart without trying to recover everything at once."},
    {"slug":"future-self-is-real","title":"Make one money decision your future self will thank you for","category":"Wealth Creation","source":"cfpb_toolkit","keywords":["goals","saving"],"geo":["global","Uganda","East Africa"],"problem":"Future needs can feel distant compared with the pressure or pleasure of today.","stakes":"Repeatedly ignoring tomorrow can reduce the choices available when circumstances change.","explanation":"Thinking about your future self makes long-term goals more concrete and can help balance immediate wants with future needs.","action":"Write a short note describing one thing you want your future finances to make possible, then choose one small step toward it."},
    {"slug":"do-not-chase-every-trend","title":"Why following every money trend can pull you away from your goals","category":"Financial Psychology","source":"sec_investor","keywords":["investing","risk"],"geo":["global"],"problem":"New financial trends can create pressure to join quickly because everyone seems to be talking about them.","stakes":"Following hype without understanding the risks can expose money to losses or scams and distract from a sound personal plan.","explanation":"A popular idea is not automatically suitable or reliable. Decisions should be based on understanding, evidence, risk and personal circumstances.","action":"Before acting on a trend, explain in your own words how it works, what could go wrong and how it is independently verified."},
    {"slug":"money-confidence-through-knowledge","title":"Confidence with money comes from understanding, not pretending","category":"Financial Literacy","source":"bou_literacy","keywords":["financial","literacy"],"geo":["Uganda","East Africa"],"problem":"People may pretend to understand financial products or decisions because they fear appearing uninformed.","stakes":"Pretending can make it harder to notice unclear terms, ask for help or avoid unsuitable choices.","explanation":"Financial confidence grows through learning, asking questions and recognising what you do not yet know.","action":"Choose one money term or decision you have been unsure about and learn it from a trusted educational source."},
    {"slug":"small-steps-beat-perfect-plans","title":"A small money habit you repeat beats a perfect plan you never start","category":"Saving and Emergency Funds","source":"cfpb_emergency","keywords":["saving","emergency"],"geo":["global","Uganda","East Africa"],"problem":"People sometimes wait for the ideal budget, income or moment before changing a money habit.","stakes":"Waiting for perfect conditions can keep useful actions from becoming part of everyday life.","explanation":"A realistic, repeatable action can build momentum and can be adjusted as circumstances change.","action":"Pick one action small enough to repeat this week and schedule the next time you will do it."},
    {"slug":"do-not-let-status-set-your-goals","title":"Your financial goals should reflect your values, not public pressure","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","financial"],"geo":["global","Uganda","East Africa"],"problem":"People may pursue expensive milestones because they are treated as proof of success by their community.","stakes":"Goals chosen for approval can consume resources without improving the life the person actually wants.","explanation":"A meaningful financial goal is connected to your needs, responsibilities and values, not simply what other people celebrate.","action":"Choose one goal that matters privately to you and write why it matters beyond other people's approval."},
    {"slug":"plan-for-obligations-before-promises","title":"Why making money promises before checking your budget causes stress","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["budget","goals"],"geo":["global","Uganda","East Africa"],"problem":"A person may agree to lend, contribute or pay for something before checking existing commitments.","stakes":"A promise made under pressure can leave essential costs uncovered or damage trust when it cannot be fulfilled.","explanation":"Responsible generosity and reliability begin with knowing what you can afford before committing.","action":"Make it a habit to check your obligations before agreeing to any non-essential financial promise."},
    {"slug":"protect-progress-from-impulse","title":"Protect your financial progress from one impulsive decision","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["spending","decisions"],"geo":["global","Uganda","East Africa"],"problem":"A sudden offer, emotional moment or social invitation can tempt someone to abandon a plan.","stakes":"One decision may undo a carefully built buffer or create a new obligation that lasts much longer than the excitement.","explanation":"A pause creates room to compare the decision with existing priorities and consider its full consequences.","action":"Create a personal rule to wait before making unplanned purchases or commitments above an amount you choose."},
    {"slug":"wealth-is-built-not-performed","title":"Wealth is built through choices, not performances","category":"Wealth Creation","source":"cfpb_toolkit","keywords":["goals","saving"],"geo":["global","Uganda","East Africa"],"problem":"It is easy to confuse visible consumption with financial progress.","stakes":"Spending to signal success can take resources away from the quiet work of reducing obligations and building resilience.","explanation":"Financial progress is often less visible than possessions: it can mean more control, fewer avoidable costs and better preparation for setbacks.","action":"Choose one invisible measure of progress, such as a bill paid on time or a small buffer built, and track it."},
    {"slug":"pay-yourself-first","title":"Why you should pay yourself first","category":"Saving and Emergency Funds","source":"cfpb_emergency","keywords":["saving","emergency"],"geo":["global","Uganda","East Africa"],"problem":"When income arrives, urgent requests and everyday spending can claim it before a person has decided what to keep for future needs.","stakes":"If saving is always left until the end, there may be nothing left consistently, even when the intention to save is genuine.","explanation":"Paying yourself first means treating a realistic saving contribution as an intentional priority when income arrives, while still protecting essential needs. It is a habit, not a promise that every person can save the same amount.","action":"When your next income arrives, decide whether a small, affordable amount can be set aside before optional spending.","inspiration":{"kind":"paraphrase","author":"George S. Clason","work":"The Richest Man in Babylon","source_url":"https://www.penguinrandomhouse.com/books/294317/the-richest-man-in-babylon-by-george-s-clason/","text":"treating saving as a priority when income arrives can help prevent every other expense from claiming the money first","verification":"author_and_original_work_verified","original_wording_reused":False,"use":"paraphrased_idea_no_direct_quote"}},
    {"slug":"every-purchase-costs-time","title":"Every purchase costs more than money","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["spending","goals"],"geo":["global","Uganda","East Africa"],"problem":"People often judge a purchase only by its price and may overlook the time and effort required to earn that money.","stakes":"Without considering the trade-off, it can be easy to exchange hours of work for things that matter less than the goals being postponed.","explanation":"A purchase can be viewed in terms of the work time and personal energy used to earn its price. This perspective can help people compare spending with their own priorities; it does not mean every purchase is wrong.","action":"Before one non-essential purchase, consider how much work time it represents and whether you would still choose it over another priority.","inspiration":{"kind":"paraphrase","author":"Vicki Robin and Joe Dominguez","work":"Your Money or Your Life","source_url":"https://www.penguinrandomhouse.com/books/303637/your-money-or-your-life-by-vicki-robin-and-joe-dominguez-foreword-by-mr-money-mustache/9780143115762/","text":"considering the life energy represented by a purchase can help people compare spending with what matters most to them","verification":"author_and_original_work_verified","original_wording_reused":False,"use":"paraphrased_idea_no_direct_quote"}},
    
    {"slug":"know-when-to-walk-away","title":"When you have already spent money, walking away can still be wise","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial"],"geo":["global","Uganda","East Africa"],"problem":"People sometimes continue paying for a plan, purchase or business idea mainly because they have already spent money, time or effort on it.","stakes":"Continuing only to avoid admitting a past loss can turn one disappointing decision into a much larger burden.","explanation":"Past spending cannot be recovered simply by spending more. A fresh decision should compare the realistic future costs and benefits of continuing with the alternatives available now.","action":"Pause and ask: if I had not already spent anything, would I choose to spend this next amount today?","inspiration":{"kind":"paraphrase","author":"Daniel Kahneman","work":"Thinking, Fast and Slow","source_url":"https://us.macmillan.com/books/9780374533557/thinkingfastandslow/","text":"our attachment to a previous choice can distort how we judge the next decision, so it helps to assess the future on its own merits","verification":"author_and_original_work_verified","original_wording_reused":False,"use":"paraphrased_idea_no_direct_quote"}},
    {"slug":"judge-the-decision-not-only-the-result","title":"A good money decision can still have a bad outcome","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial"],"geo":["global","Uganda","East Africa"],"problem":"When a decision turns out badly, people may assume the decision itself was foolish; when it turns out well, they may assume the process was excellent.","stakes":"Judging decisions only by their outcomes can teach the wrong lesson and encourage repeated risks or unnecessary fear.","explanation":"Uncertainty means a thoughtful decision can still end badly, while a careless decision can sometimes succeed by chance. Reviewing the information, risks and reasoning available at the time gives a fairer lesson.","action":"After an important money decision, write down what you knew, what risks you considered and what you would improve next time—separately from the result.","inspiration":{"kind":"paraphrase","author":"Annie Duke","work":"Thinking in Bets","source_url":"https://www.penguinrandomhouse.com/books/552885/thinking-in-bets-by-annie-duke/","text":"decision quality should be judged by the reasoning available at the time, not simply by whether the outcome was favourable","verification":"author_and_original_work_verified","original_wording_reused":False,"use":"paraphrased_idea_no_direct_quote"}},
    {"slug":"luck-is-not-a-repeatable-money-plan","title":"Do not mistake a lucky result for a reliable money strategy","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial"],"geo":["global","Uganda","East Africa"],"problem":"A person may see someone make money once and assume that the same approach will keep working for everyone.","stakes":"Confusing luck with skill can create overconfidence, imitation and exposure to risks that are not properly understood.","explanation":"Outcomes are influenced by both decisions and events outside anyone's control. One success does not prove that a method is reliable or that its risks are acceptable.","action":"Before copying a money-making story, ask what could have gone wrong, what role chance played and whether there is evidence the approach works consistently.","inspiration":{"kind":"paraphrase","author":"Nassim Nicholas Taleb","work":"Fooled by Randomness","source_url":"https://www.penguinrandomhouse.com/books/176225/fooled-by-randomness-by-nassim-nicholas-taleb/","text":"chance can make an uncertain outcome look like proof of skill, so a single success should not be treated as a dependable formula","verification":"author_and_original_work_verified","original_wording_reused":False,"use":"paraphrased_idea_no_direct_quote"}},

    # New batch: distinct money-management and investor-behaviour lessons, screened against earlier blueprints.
    {"slug":"money-needs-a-regular-check-in","title":"Your money needs a regular check-in, not an annual resolution","category":"Budgeting and Money Management","source":"cfpb_wellbeing","keywords":["control","goals"],"geo":["global","Uganda","East Africa"],"problem":"People may make a money plan once, then avoid reviewing it until a problem forces their attention back to it.","stakes":"Without regular check-ins, changing bills, priorities and habits can quietly push a plan away from real life.","explanation":"Financial control is maintained through small, repeated decisions. A short review helps people notice changes early and adjust without treating every change as failure.","action":"Choose one day each week or month to review what came in, what went out and whether your priorities still make sense."},
    {"slug":"define-enough-before-comparison","title":"Decide what enough means before comparison moves the goalposts","category":"Financial Psychology","source":"cfpb_wellbeing","keywords":["freedom","goals"],"geo":["global","Uganda","East Africa"],"problem":"Without a personal definition of enough, each new example of someone else's lifestyle can make a person's own progress feel inadequate.","stakes":"The target keeps moving, so people may spend more, take on pressure or postpone satisfaction without getting closer to what actually matters.","explanation":"Financial well-being is connected to security and freedom of choice, not a universal income or lifestyle target. Personal values help define what progress should mean.","action":"Write down three things that would make your financial life feel more secure or meaningful, without comparing them with another person's possessions."},
    {"slug":"annual-expenses-are-not-surprises","title":"Annual expenses are not surprises if you plan for them","category":"Budgeting and Money Management","source":"fdic_money_smart","keywords":["expenses","saving"],"geo":["global","Uganda","East Africa"],"problem":"School costs, renewals, seasonal travel, celebrations and repairs can feel like emergencies when they arrive, even if they happen regularly.","stakes":"Treating predictable costs as surprises can disrupt everyday spending plans and lead to rushed borrowing.","explanation":"Some expenses are irregular but predictable. Recognising their timing and preparing gradually can make them easier to handle than pretending they will not arrive.","action":"List three costs that usually appear once or a few times a year, note when they are due and plan how to prepare for them."},
    {"slug":"records-create-clarity-not-guilt","title":"Keeping money records creates clarity, not a reason for guilt","category":"Financial Psychology","source":"fdic_money_smart","keywords":["expenses","spending"],"geo":["global","Uganda","East Africa"],"problem":"People may avoid receipts, statements or simple records because they fear what the numbers will reveal.","stakes":"Without a clear record, it is harder to recognise patterns, remember commitments or make informed adjustments.","explanation":"A record is a source of information, not a verdict on someone's character. Looking at actual activity can replace guesswork with choices.","action":"For the next seven days, keep a simple record of money received and spent; review it with curiosity rather than criticism."},
    {"slug":"agree-on-money-before-shared-commitments","title":"Agree on money expectations before making shared commitments","category":"Financial Psychology","source":"cfpb_habits","keywords":["decisions","goals"],"geo":["global","Uganda","East Africa"],"problem":"Friends, partners or relatives may agree to rent, travel, purchases or support arrangements without first discussing who will pay what.","stakes":"Unspoken assumptions can turn a shared plan into conflict, missed payments or resentment.","explanation":"Clear expectations make shared financial decisions easier to understand. A respectful conversation before committing gives everyone a chance to raise limits and alternatives.","action":"Before agreeing to a shared expense, discuss the total cost, each person's contribution, the due date and what happens if circumstances change."},
    {"slug":"routine-beats-waiting-for-motivation","title":"A simple money routine works when motivation disappears","category":"Financial Psychology","source":"cfpb_habits","keywords":["habits","planning"],"geo":["global","Uganda","East Africa"],"problem":"People may wait to feel motivated before reviewing bills, saving or checking their progress.","stakes":"When motivation fades or life gets busy, important actions can be postponed repeatedly.","explanation":"A routine reduces the need to make the same decision from scratch. Small cues and repeatable steps can support habits through ordinary changes in mood.","action":"Attach one money task to an existing routine, such as reviewing expenses after a weekly planning session."},
    {"slug":"spending-should-reflect-values-not-mood","title":"Let your values guide spending more than the mood of the moment","category":"Financial Psychology","source":"fdic_money_smart","keywords":["values","spending"],"geo":["global","Uganda","East Africa"],"problem":"A temporary mood can make a purchase feel more important than the priorities a person chose when thinking calmly.","stakes":"Repeated mood-led decisions can create regret and leave less room for goals that matter over time.","explanation":"Money choices are influenced by values, emotions and outside pressures. Pausing to reconnect a decision with personal priorities can make spending more intentional.","action":"Before a non-essential purchase, ask which personal value or goal it supports and whether that still feels important tomorrow."},
    {"slug":"plans-can-adapt-without-being-abandoned","title":"Changing your money plan is not the same as giving up","category":"Budgeting and Money Management","source":"cfpb_wellbeing","keywords":["control","choices"],"geo":["global","Uganda","East Africa"],"problem":"When income, family needs or costs change, some people see their original plan no longer fits and abandon the whole thing.","stakes":"An all-or-nothing approach can turn a temporary disruption into a longer period without direction.","explanation":"A useful plan should respond to real circumstances. Revising priorities is often more practical than pretending nothing changed or treating adjustment as failure.","action":"When something changes, update the next few priorities and restart with the resources you actually have."},
    {"slug":"one-hard-month-is-not-your-whole-story","title":"One difficult month does not define your financial future","category":"Financial Psychology","source":"cfpb_wellbeing","keywords":["security","goals"],"geo":["global","Uganda","East Africa"],"problem":"A setback can make people feel that all earlier effort was wasted and that improvement is no longer possible.","stakes":"That belief can encourage avoidance or decisions made from discouragement rather than from the situation in front of them.","explanation":"Financial progress is rarely a perfectly straight line. A difficult period is important information, but it does not erase skills, learning or options that remain available.","action":"Name what changed, identify what still works and choose one manageable next step instead of trying to repair everything at once."},
    {"slug":"pause-before-emotional-money-decisions","title":"Pause before making important money decisions in a strong emotion","category":"Financial Psychology","source":"cfpb_habits","keywords":["decisions","habits"],"geo":["global","Uganda","East Africa"],"problem":"Excitement, fear, anger or embarrassment can create pressure to make a financial decision immediately.","stakes":"A rushed choice may commit money or create obligations before the person has considered alternatives and consequences.","explanation":"Strong emotions can narrow attention. A deliberate pause gives time to gather information, ask questions and decide whether the urgency is real.","action":"For a non-emergency financial decision, step away briefly and return with three questions: what do I know, what could go wrong and what alternatives do I have?"},
    {"slug":"make-progress-visible-not-perfection","title":"Make your financial progress visible instead of demanding perfection","category":"Wealth Creation","source":"cfpb_wellbeing","keywords":["goals","progress"],"geo":["global","Uganda","East Africa"],"problem":"People may overlook small improvements because they compare themselves with an ideal outcome or someone much further ahead.","stakes":"If progress never feels good enough, it becomes harder to sustain the actions that are already helping.","explanation":"Financial goals are easier to work toward when progress is observable and measured against a realistic starting point. The path can include pauses and adjustments.","action":"Choose one behaviour you want to repeat and record each time you complete it; review consistency rather than expecting a perfect streak."},
    {"slug":"familiar-investment-is-not-automatically-safe","title":"A familiar investment is not automatically a safe investment","category":"Investing Fundamentals","source":"sec_behavior","keywords":["familiarity","risk"],"geo":["global"],"problem":"People may feel more comfortable with a company, product or industry they recognise, even when they have not examined its risks.","stakes":"Familiarity can be mistaken for evidence, leading to concentrated decisions or confidence that is not supported by research.","explanation":"Recognising a name is not the same as understanding its financial condition, risks or suitability. Investor education materials identify familiarity bias as a behaviour that can undermine decisions.","action":"Before considering an investment, write down what you know from reliable information, what remains uncertain and what risks you may be overlooking."},
    {"slug":"past-investment-performance-is-not-a-promise","title":"Past investment performance is a record, not a promise","category":"Investing Fundamentals","source":"sec_behavior","keywords":["performance","investing"],"geo":["global"],"problem":"A strong recent result can make an investment appear certain to keep performing well.","stakes":"Chasing yesterday's winners can lead people to overlook changing conditions, costs and the possibility of losses.","explanation":"Past performance alone cannot establish what an investment will do next. Reviewing risk, fees, time horizon and the reasons behind a decision is more responsible than relying on a recent chart.","action":"When you see a performance claim, ask what period it covers, what risks were taken and what information is missing before drawing conclusions."},
    {"slug":"more-investment-activity-is-not-always-progress","title":"More investment activity does not automatically mean better decisions","category":"Investing Fundamentals","source":"sec_behavior","keywords":["trading","performance"],"geo":["global"],"problem":"Constantly buying and selling can feel like taking control, especially when prices and headlines keep changing.","stakes":"Frequent activity can increase costs and encourage reactions to short-term noise rather than a considered plan.","explanation":"The SEC's investor education material identifies active trading as one behaviour that can undermine investment performance. Activity by itself is not proof of good decision-making.","action":"Before making a change, write down the specific reason, the evidence supporting it and how it fits the goal and risk you originally considered."},
    {"slug":"panic-is-not-an-investment-strategy","title":"Panic is not an investment strategy","category":"Investing Fundamentals","source":"sec_behavior","keywords":["panic","manias"],"geo":["global"],"problem":"Sharp market movements and alarming stories can create pressure to copy what everyone else is doing.","stakes":"Decisions made in a rush may abandon a person's original time horizon or risk understanding without considering the full situation.","explanation":"Investor.gov describes manias and panics as behavioural patterns that can undermine investor decisions. This is a reminder to distinguish new evidence from emotional crowd reactions.","action":"When market news feels alarming, pause, verify the information and revisit the reasons and time horizon behind your own decision before acting."},
    {"slug":"popularity-is-not-due-diligence","title":"A popular investment still deserves independent research","category":"Investing Fundamentals","source":"sec_behavior","keywords":["momentum","research"],"geo":["global"],"problem":"A rising trend, viral story or enthusiastic group can make an investment appear credible before a person has checked it.","stakes":"Popularity can create pressure to follow others and can hide risks that are not visible in a short success story.","explanation":"Momentum and crowd behaviour are recognised investor decision risks. Popularity tells you that people are paying attention; it does not establish value, suitability or safety.","action":"Before following a trend, find independent information about the investment, its risks, costs and the possibility of losing money."},
    {"slug":"many-investments-do-not-guarantee-diversification","title":"Owning many investments does not automatically mean you are diversified","category":"Investing Fundamentals","source":"sec_behavior","keywords":["diversification","risk"],"geo":["global"],"problem":"A portfolio may contain many names but still depend heavily on similar companies, industries or risks.","stakes":"The appearance of variety can create a false sense of protection if the holdings respond to the same events.","explanation":"Investor education materials distinguish genuine diversification from simply owning multiple investments. Understanding what drives each holding matters more than counting them.","action":"When learning about a portfolio, look at what the holdings actually represent and whether they share the same major risks; seek qualified advice for personal decisions."},
    {"slug":"fees-deserve-attention-before-performance","title":"Do not overlook fees while focusing on investment performance","category":"Investing Fundamentals","source":"sec_behavior","keywords":["fees","performance"],"geo":["global"],"problem":"People may focus on a headline return or recent gain while paying little attention to the costs involved.","stakes":"Costs can reduce what remains for an investor, and ignoring them makes comparisons less meaningful.","explanation":"Investor.gov identifies focusing on past performance while ignoring fees as a behavioural pitfall. Understanding costs is part of evaluating an investment, not a minor afterthought.","action":"When comparing investment information, look for the full fee and cost disclosures as well as the performance figures."},
    {"slug":"write-down-why-before-changing-an-investment-plan","title":"Write down your reasons before changing an investment plan","category":"Investing Fundamentals","source":"sec_behavior","keywords":["decisions","risk"],"geo":["global"],"problem":"When prices move or opinions change, people may forget why they made an earlier decision and react to the latest story.","stakes":"Without a clear record of the original reasoning, it is harder to distinguish a meaningful change in circumstances from temporary noise.","explanation":"A written rationale makes it easier to review whether new information genuinely changes the decision. It does not guarantee a good outcome, but it can make the reasoning more deliberate.","action":"Before changing an investment decision, write down the original goal, the new information and what specifically has changed."},
    {"slug":"check-the-source-before-sharing-money-claims","title":"Check the source before sharing a money claim with others","category":"Financial Psychology","source":"cfpb_habits","keywords":["information","decisions"],"geo":["global","Uganda","East Africa"],"problem":"A dramatic money story or financial tip can spread quickly through group chats and personal networks before anyone checks where it came from.","stakes":"Repeating unverified claims can expose friends and relatives to confusion, pressure or harmful decisions.","explanation":"Financial confidence includes knowing when to pause and verify information. A claim repeated by many people is not necessarily accurate or relevant to every situation.","action":"Before forwarding a financial claim, find its original source, check the date and look for confirmation from a credible institution."},
    {"slug":"ask-for-clarity-without-feeling-embarrassed","title":"Asking for clarity is a strength, not a sign of weakness","category":"Financial Psychology","source":"fdic_money_smart","keywords":["services","questions"],"geo":["global","Uganda","East Africa"],"problem":"People may stay silent when they do not understand a financial term, fee, condition or responsibility because they fear looking inexperienced.","stakes":"Unanswered questions can leave people agreeing to obligations they do not fully understand.","explanation":"Financial decisions often involve unfamiliar language. Taking time to ask for a plain explanation supports informed choices and personal control.","action":"When something is unclear, ask the person explaining it to define the term, describe the total obligation and show where the condition appears in writing."},
]); 
